package edu.washington.gs.maccoss.encyclopedia.utils.massspec;

import java.util.ArrayList;

import edu.washington.gs.maccoss.encyclopedia.datastructures.AminoAcidConstants;
import edu.washington.gs.maccoss.encyclopedia.datastructures.FastaEntry;
import edu.washington.gs.maccoss.encyclopedia.datastructures.ModificationMassMap;
import gnu.trove.map.hash.TCharDoubleHashMap;
import junit.framework.TestCase;

public class ExtendedDigestionEnzymeTest extends TestCase {
	private static final DigestionEnzyme enzyme=DigestionEnzyme.getEnzyme("Trypsin");
	public void testAAAAAARLNR() {
		String sequence="";
		String target="AAAAAARLNR";
		
		ArrayList<String> set=enzyme.digestProtein(new FastaEntry(sequence), 5, 40, 1, new AminoAcidConstants(new TCharDoubleHashMap(), new ModificationMassMap()));
		assertTrue(set.contains(target));
	}

	public void testAAVRETHK() {
		String sequence="";
		String target="AAVRETHK";
		ArrayList<String> set=enzyme.digestProtein(new FastaEntry(sequence), 5, 40, 1, new AminoAcidConstants(new TCharDoubleHashMap(), new ModificationMassMap()));
		assertTrue(set.contains(target));
	}
	
	public void testAAACPSSPHK() {
		String sequence="";
		String target="AAACPSSPHK";
		ArrayList<String> set=enzyme.digestProtein(new FastaEntry(sequence), 5, 40, 1, new AminoAcidConstants(new TCharDoubleHashMap(), new ModificationMassMap()));
		assertTrue(set.contains(target));
	}
	
}
